/**
 * backtest-replay.types.ts
 *
 * Types for the event-driven BacktestReplayEngine.
 *
 * Distinct from the existing BacktestTrade/BacktestResult approach:
 *   - BacktestTrade: a pre-computed trade record supplied by the caller.
 *   - ReplayTrade:   a trade record generated by running the actual scanner
 *     logic against stored candle data, with no look-ahead.
 *
 * Requirements: Phase 5 — Event-Driven Backtesting
 */

/** All six strategy codes implemented in StrategyEntryConditionsService. */
export type ReplayStrategyCode = 'A' | 'B' | 'C' | 'D' | 'E' | 'F';

/** How the synthetic NIFTY spot was derived. */
export type SpotDerivationMethod =
  | 'DIRECT' // actual underlying candles available
  | 'PUT_CALL_PARITY' // spot = strike + CE_close − PE_close
  | 'CE_INTRINSIC' // spot ≈ strike + CE_close (when only CE available)
  | 'NONE'; // spot could not be derived

/** Exit reason for a replayed trade. */
export type ReplayExitReason =
  'STOP_LOSS' | 'TARGET_HIT' | 'EOD_SQUARE_OFF' | 'SIGNAL_REVERSAL' | 'NO_DATA';

/** One simulated trade produced by the replay engine. */
export interface ReplayTrade {
  /** Trading date (YYYY-MM-DD IST). */
  date: string;
  /** Strategy that generated the entry signal. */
  strategyCode: ReplayStrategyCode;
  /** Direction of the signal on the underlying. */
  underlyingDirection: 'BULLISH' | 'BEARISH';
  /** CE or PE selected for the trade. */
  optionType: 'CE' | 'PE';
  /** Strike price of the selected option. */
  strike: number;
  /** Underlying price at signal time (synthetic spot). */
  underlyingAtEntry: number;
  /** Synthetic-spot derivation method. */
  spotDerivationMethod: SpotDerivationMethod;
  /** Time of entry signal (IST HH:MM). */
  signalTime: string;
  /** Time of execution (1 candle after signal, IST HH:MM). */
  entryTime: string;
  /** Entry price (option premium at next-candle open). */
  entryPrice: number;
  /** Stop-loss price (option premium). */
  stopLossPrice: number;
  /** Target price (option premium). */
  targetPrice: number;
  /** Time of exit (IST HH:MM). */
  exitTime: string;
  /** Exit reason. */
  exitReason: ReplayExitReason;
  /** Exit price (option premium). */
  exitPrice: number;
  /** Lot size (always 65 for NIFTY as of 2026). */
  lotSize: number;
  /** Number of lots traded (1). */
  lots: number;
  /** Total units (lots × lotSize). */
  quantity: number;
  /** Gross P&L before costs (₹). */
  grossPnl: number;
  /** All trading costs (₹). */
  totalCosts: number;
  /** Net P&L after costs (₹). */
  netPnl: number;
  /** Regime label at entry. */
  regime: string;
  /** Maximum adverse excursion during the trade (₹, positive = loss). */
  mae: number;
  /** Maximum favourable excursion during the trade (₹, positive = gain). */
  mfe: number;
  /** All indicator values at signal time. */
  indicatorsAtSignal: Record<string, number | null>;
  /** Detailed entry-condition results for observability. */
  strategyConditions: Array<{ name: string; passed: boolean; value: string }>;
}

/** Aggregate performance metrics for a strategy. */
export interface ReplayStrategyMetrics {
  strategyCode: ReplayStrategyCode;
  strategyName: string;
  /** Total scanning days. */
  tradingDays: number;
  /** Days where at least one signal fired. */
  signalDays: number;
  /** Total signals generated. */
  totalSignals: number;
  /** Signals rejected by liquidity/price/expiry checks. */
  rejectedSignals: number;
  /** Trades actually executed. */
  tradesExecuted: number;
  /** Winning trades (net P&L > 0). */
  wins: number;
  /** Losing trades. */
  losses: number;
  /** Win rate (0–100). */
  winRate: number;
  /** Gross P&L across all trades (₹). */
  grossPnl: number;
  /** Total costs (₹). */
  totalCosts: number;
  /** Net P&L (₹). */
  netPnl: number;
  /** Net P&L per trade (₹). */
  expectancy: number;
  /** Profit factor (gross wins / gross losses). */
  profitFactor: number;
  /** Maximum peak-to-trough drawdown of cumulative net P&L curve (₹). */
  maxDrawdown: number;
  /** Average holding time in minutes. */
  avgHoldingMinutes: number;
  /** % of trades exiting EOD (indicates missed targets). */
  eodExitPct: number;
  /** % of trades exiting at stop-loss. */
  stopLossExitPct: number;
  /** % of trades hitting target. */
  targetHitPct: number;
  /** Average MAE per trade (₹). */
  avgMae: number;
  /** Average MFE per trade (₹). */
  avgMfe: number;
  /** 95% bootstrap CI for expectancy (₹). */
  expectancyCI: { mean: number; lower95: number; upper95: number };
  /** All individual trades. */
  trades: ReplayTrade[];
}

/** Walk-forward window result. */
export interface WalkForwardWindow {
  windowNumber: number;
  inSampleFrom: string;
  inSampleTo: string;
  outSampleFrom: string;
  outSampleTo: string;
  inSampleMetrics: Omit<ReplayStrategyMetrics, 'trades' | 'expectancyCI'>;
  outSampleMetrics: Omit<ReplayStrategyMetrics, 'trades' | 'expectancyCI'>;
  outSampleExpectancyCI: { mean: number; lower95: number; upper95: number };
}

/** Full result of a replay backtest run. */
export interface ReplayBacktestResult {
  /** Version tag for reproducibility. */
  version: string;
  /** Time this backtest was run. */
  ranAt: string;
  /** Data range used. */
  dataFromDate: string;
  dataToDate: string;
  /** Number of trading days replayed. */
  tradingDaysReplayed: number;
  /** Total candles processed. */
  candlesProcessed: number;
  /** How spot price was derived. */
  spotDerivationMethod: SpotDerivationMethod;
  /** Strike used for synthetic spot / ATM selection. */
  atmStrike: number;
  /** In-sample / out-of-sample split ratio (0.7 = 70% IS). */
  inSampleRatio: number;
  /** Cut-off date for IS vs OOS split. */
  splitDate: string;
  /** Per-strategy results. */
  strategies: ReplayStrategyMetrics[];
  /** Combined engine result (all strategies, one trade per day — highest-scored). */
  combined: ReplayStrategyMetrics;
  /** Walk-forward windows (3 windows across the data). */
  walkForward: WalkForwardWindow[];
  /** Summary verdict. */
  verdict: {
    sufficientSample: boolean;
    oosPositiveExpectancy: boolean;
    oosWinRateAbove50: boolean;
    profitFactorAbove1: boolean;
    maxDrawdownAcceptable: boolean;
    conclusion: string;
  };
  /** Any data quality warnings encountered. */
  warnings: string[];
}

/** Request body for POST /backtest/replay. */
export interface ReplayBacktestRequest {
  /**
   * Strategies to run. Default: all 6 (A–F).
   * Specify a subset to test individual strategies.
   */
  strategies?: ReplayStrategyCode[];
  /**
   * In-sample ratio for IS/OOS split. Default: 0.70 (70% in-sample).
   * Valid range: 0.5 – 0.9.
   */
  inSampleRatio?: number;
  /**
   * SL percentage on option premium (e.g. 0.15 = 15% SL below entry).
   * Default: 0.15.
   */
  stopLossPct?: number;
  /**
   * Target percentage on option premium (e.g. 0.25 = 25% target above entry).
   * Default: 0.25.
   */
  targetPct?: number;
  /**
   * Minimum RSI on synthetic spot for BULLISH entry (Strategies A, B, C, F).
   * Default: 55.
   */
  minRsiBull?: number;
  /**
   * Maximum RSI on synthetic spot for BEARISH entry.
   * Default: 45.
   */
  maxRsiBear?: number;
  /**
   * Minimum relative volume multiplier for all strategy conditions.
   * Default: 1.2.
   */
  minRelVol?: number;
  /**
   * Number of walk-forward windows.
   * Default: 3.
   */
  walkForwardWindows?: number;
  /**
   * Maximum drawdown in rupees before the replay stops adding new positions.
   * Default: 50000 (₹50,000).
   */
  maxDrawdownRupees?: number;
}
